<script>
export default {
  name: "InternalApplicantProfile",

  props: {
    practitionerId: {
      type: String,
      required: true,
    },
  },

  data() {
    return {
      tab: 0,
      loading: true,
      practitioner: {},
      roles: [],
      educationHistory: [],
      employmentHistory: [],
      studyLeaveEducation: [],
      slQualificationNames: [],
      eduQualificationNames: [],
    };
  },

  computed: {
    profileFullName() {
      const name = this.practitioner.name?.[0];
      if (!name) return "—";
      const given = (name.given || []).join(" ");
      const family = name.family || "";
      return [given, family].filter(Boolean).join(" ") || "—";
    },

    profileInitials() {
      const name = this.practitioner.name?.[0];
      if (!name) return "?";
      const given = name.given?.[0]?.[0] || "";
      const family = name.family?.[0] || "";
      return (given + family).toUpperCase() || "?";
    },

    currentRole() {
      return this.roles.find((r) => r.active) || this.roles[0] || null;
    },
  },

  async mounted() {
    await this.loadProfile();
  },

  methods: {
    async loadProfile() {
      this.loading = true;
      try {
        const [
          practRes,
          rolesRes,
          eduRes,
          emplRes,
          studyLeaveRes,
        ] = await Promise.all([
          fetch(`/fhir/Practitioner/${this.practitionerId}`).then((r) =>
            r.ok ? r.json() : null,
          ),
          fetch(
            `/site/position/practitioner/${this.practitionerId}/role-history`,
          ).then((r) => (r.ok ? r.json() : { roles: [] })),
          fetch(
            `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/education-history-profile&practitioner=Practitioner/${this.practitionerId}&_count=50`,
          ).then((r) => (r.ok ? r.json() : { entry: [] })),
          fetch(
            `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/ihris-basic-employment-history&practitioner=Practitioner/${this.practitionerId}&_count=50`,
          ).then((r) => (r.ok ? r.json() : { entry: [] })),
          fetch(
            `/fhir/Basic?_profile=http://ihris.org/fhir/StructureDefinition/study-leave-profile&practitioner=Practitioner/${this.practitionerId}&trainingcompletionstatus=completed&_count=50`,
          ).then((r) => (r.ok ? r.json() : { entry: [] })),
        ]);

        this.practitioner = practRes || {};
        this.roles = rolesRes.roles || [];
        this.educationHistory = (eduRes.entry || []).map((e) => e.resource);
        this.eduQualificationNames = await Promise.all(
          this.educationHistory.map((edu) =>
            this.resolveQualificationNameFromExts(this.ehExt(edu)),
          ),
        );
        this.employmentHistory = (emplRes.entry || []).map((e) => e.resource);
        this.studyLeaveEducation = (studyLeaveRes.entry || []).map(
          (e) => e.resource,
        );
        this.slQualificationNames = await Promise.all(
          this.studyLeaveEducation.map((sl) =>
            this.resolveQualificationName(sl),
          ),
        );
      } catch (e) {
        console.error("InternalApplicantProfile loadProfile error", e);
      } finally {
        this.loading = false;
      }
    },

    fmtDate(val) {
      if (!val) return null;
      const d = new Date(val);
      if (isNaN(d.getTime())) return val;
      return d.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },

    // Education history helpers
    ehExt(edu) {
      return (
        (edu.extension || []).find((x) => x.url.endsWith("/education-history"))
          ?.extension || []
      );
    },
    ehSub(edu, subUrl, field = "valueString") {
      const child = this.ehExt(edu).find((x) => x.url === subUrl);
      return child ? child[field] ?? null : null;
    },
    ehSubCoding(edu, subUrl) {
      const child = this.ehExt(edu).find((x) => x.url === subUrl);
      return child?.valueCoding?.display || child?.valueCoding?.code || null;
    },
    ehAllSubs(edu, subUrl) {
      return this.ehExt(edu)
        .filter((x) => x.url === subUrl)
        .map((x) => x.valueString)
        .filter(Boolean);
    },

    // Completed study-leave qualification helpers
    slExtVal(sl, url, field = "valueString") {
      const ext = (sl.extension || []).find((x) => x.url.endsWith("/" + url));
      return ext ? ext[field] ?? null : null;
    },
    slCoding(sl, url) {
      const ext = (sl.extension || []).find((x) => x.url.endsWith("/" + url));
      return ext?.valueCoding?.display || ext?.valueCoding?.code || null;
    },
    slString(sl, url) {
      return this.slExtVal(sl, url, "valueString");
    },
    slCompletionExt(sl) {
      return (
        (sl.extension || []).find((x) => x.url.endsWith("/training-completion"))
          ?.extension || []
      );
    },
    slOutcome(sl) {
      const ext = this.slCompletionExt(sl).find(
        (x) => x.url === "training-outcome",
      );
      return ext?.valueCoding?.display || ext?.valueCoding?.code || null;
    },
    slCompletionDate(sl) {
      return (
        this.slCompletionExt(sl).find((x) => x.url === "completion-date")
          ?.valueDate || null
      );
    },
    slCompletionField(sl, subUrl, field = "valueString") {
      const ext = this.slCompletionExt(sl).find((x) => x.url === subUrl);
      return ext ? ext[field] ?? null : null;
    },
    async resolveQualificationName(resource) {
      return this.resolveQualificationNameFromExts(resource.extension || []);
    },
    async resolveQualificationNameFromExts(exts) {
      const matchesUrl = (e, name) =>
        e.url === name || e.url.endsWith("/" + name);

      const qualNameOtherExt = (exts || []).find((e) =>
        matchesUrl(e, "qualification-name-other"),
      );
      if (qualNameOtherExt?.valueString) return qualNameOtherExt.valueString;

      const qualNameExt = (exts || []).find((e) =>
        matchesUrl(e, "qualification-name"),
      );
      if (qualNameExt?.valueReference?.display) {
        return qualNameExt.valueReference.display;
      }

      const ref = qualNameExt?.valueReference?.reference;
      if (!ref) return null;
      try {
        const id = ref.split("/")[1];
        const response = await fetch(`/fhir/Basic/${id}`);
        if (!response.ok) return null;

        const qualification = await response.json();
        let name = qualification.extension?.find(
          (ext) =>
            ext.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-basic-name",
        )?.valueString;
        return name;
      } catch (error) {
        console.error("Error resolving qualification name:", error);
        return null;
      }
    },

    // Prior employment history helpers
    eplExt(empl) {
      return (
        (empl.extension || []).find((x) =>
          x.url.endsWith("/ihris-employment-history"),
        )?.extension || []
      );
    },
    eplSub(empl, subUrl, field = "valueString") {
      const child = this.eplExt(empl).find((x) => x.url === subUrl);
      return child ? child[field] ?? null : null;
    },
    eplSubCoding(empl, subUrl) {
      const child = this.eplExt(empl).find((x) => x.url === subUrl);
      return child?.valueCoding?.display || child?.valueCoding?.code || null;
    },
    eplAllSubs(empl, subUrl, field = "valueString") {
      return this.eplExt(empl)
        .filter((x) => x.url === subUrl)
        .map((x) => x[field])
        .filter(Boolean);
    },
  },
};
</script>

